import { describe, it, expect, vi, beforeEach } from "vitest";
import { GET, POST } from "./route";
import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";

vi.mock("next-auth", () => ({
  getServerSession: vi.fn(),
}));

vi.mock("@/lib/prisma", () => ({
  default: {
    userProfile: {
      findUnique: vi.fn(),
      upsert: vi.fn(),
    },
    goal: {
      findUnique: vi.fn(),
      upsert: vi.fn(),
    },
    user: {
      update: vi.fn(),
      findUnique: vi.fn(),
    },
  },
}));

describe("Profile API Route", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe("GET", () => {
    it("returns 401 if not authenticated", async () => {
      vi.mocked(getServerSession).mockResolvedValue(null);
      const req = new Request("http://localhost/api/profile");
      const res = await GET(req);
      expect(res.status).toBe(401);
    });

    it("returns profile data for authenticated user", async () => {
      const mockSession = { user: { id: "user-1", email: "test@example.com" } };
      vi.mocked(getServerSession).mockResolvedValue(mockSession as any);

      const mockProfile = { userId: "user-1", age: 30, gender: "Male" };
      const mockUser = {
        name: "Test User",
        email: "test@example.com",
        phone: null,
        username: null,
      };
      vi.mocked(prisma.userProfile.findUnique).mockResolvedValue(
        mockProfile as any,
      ); // eslint-disable-line @typescript-eslint/no-explicit-any
      vi.mocked(prisma.user.findUnique).mockResolvedValue(mockUser as any);

      const req = new Request("http://localhost/api/profile");
      const res = await GET(req);
      const data = await res.json();

      expect(res.status).toBe(200);
      expect(data).toEqual({ ...mockProfile, ...mockUser });
      expect(prisma.userProfile.findUnique).toHaveBeenCalledWith({
        where: { userId: "user-1" },
      });
      expect(prisma.user.findUnique).toHaveBeenCalledWith({
        where: { id: "user-1" },
      });
    });

    it("returns goal data when type=goals is requested", async () => {
      const mockUser = { id: "user-1" };
      vi.mocked(getServerSession).mockResolvedValue({ user: mockUser });

      const mockGoal = { userId: "user-1", proteinTarget: 150 };
      vi.mocked(prisma.goal.findUnique).mockResolvedValue(mockGoal as any); // eslint-disable-line @typescript-eslint/no-explicit-any

      const req = new Request("http://localhost/api/profile?type=goals");
      const res = await GET(req);
      const data = await res.json();

      expect(res.status).toBe(200);
      expect(data).toEqual(mockGoal);
      expect(prisma.goal.findUnique).toHaveBeenCalledWith({
        where: { userId: "user-1" },
      });
    });
  });

  describe("POST", () => {
    it("returns 401 if not authenticated", async () => {
      vi.mocked(getServerSession).mockResolvedValue(null);
      const req = new Request("http://localhost/api/profile", {
        method: "POST",
        body: JSON.stringify({}),
      });
      const res = await POST(req);
      expect(res.status).toBe(401);
    });

    it("updates profile data", async () => {
      const mockUser = { id: "user-1" };
      vi.mocked(getServerSession).mockResolvedValue({ user: mockUser });

      const updateData = { age: 31, gender: "Male", name: "New Name" };
      vi.mocked(prisma.userProfile.upsert).mockResolvedValue({
        userId: "user-1",
        ...updateData,
      } as any); // eslint-disable-line @typescript-eslint/no-explicit-any

      const req = new Request("http://localhost/api/profile", {
        method: "POST",
        body: JSON.stringify(updateData),
      });
      const res = await POST(req);
      await res.json();

      expect(res.status).toBe(200);
      expect(prisma.userProfile.upsert).toHaveBeenCalled();
      expect(prisma.user.update).toHaveBeenCalledWith({
        where: { id: "user-1" },
        data: { name: "New Name" },
      });
    });

    it("updates goal data if goal fields are present", async () => {
      const mockUser = { id: "user-1" };
      vi.mocked(getServerSession).mockResolvedValue({ user: mockUser });

      const goalData = { proteinTarget: 180, kcalTarget: 2500 };
      vi.mocked(prisma.goal.upsert).mockResolvedValue({
        userId: "user-1",
        ...goalData,
      } as any); // eslint-disable-line @typescript-eslint/no-explicit-any

      const req = new Request("http://localhost/api/profile", {
        method: "POST",
        body: JSON.stringify(goalData),
      });
      const res = await POST(req);
      await res.json();

      expect(res.status).toBe(200);
      expect(prisma.goal.upsert).toHaveBeenCalled();
    });

    it("returns 400 for invalid profile data", async () => {
      const mockUser = { id: "user-1" };
      vi.mocked(getServerSession).mockResolvedValue({ user: mockUser });

      const invalidData = { age: "invalid" }; // age should be number (forced by schema)
      const req = new Request("http://localhost/api/profile", {
        method: "POST",
        body: JSON.stringify(invalidData),
      });
      const res = await POST(req);
      const data = await res.json();

      expect(res.status).toBe(400);
      expect(data).toHaveProperty("error");
    });

    it("returns 400 for invalid goal data in POST", async () => {
      vi.mocked(getServerSession).mockResolvedValue({ user: { id: "user-1" } });
      const res = await POST(
        new Request("http://localhost/api/profile", {
          method: "POST",
          body: JSON.stringify({ proteinTarget: -10 }),
        }),
      );
      expect(res.status).toBe(400);
    });

    it("returns 500 if database fails on GET", async () => {
      vi.mocked(getServerSession).mockResolvedValue({ user: { id: "user-1" } });
      vi.mocked(prisma.userProfile.findUnique).mockRejectedValueOnce(
        new Error("DB Error"),
      );
      const res = await GET(new Request("http://localhost/api/profile"));
      expect(res.status).toBe(500);
    });

    it("returns 500 if database fails on POST", async () => {
      vi.mocked(getServerSession).mockResolvedValue({ user: { id: "user-1" } });
      vi.mocked(prisma.userProfile.upsert).mockRejectedValueOnce(
        new Error("DB Error"),
      );
      const res = await POST(
        new Request("http://localhost/api/profile", {
          method: "POST",
          body: JSON.stringify({ age: 30 }),
        }),
      );
      expect(res.status).toBe(500);
    });
  });
});

import { GET, POST } from './route';
import { getServerSession } from 'next-auth';
import prisma from '@/lib/prisma';
import { describe, it, expect, vi, beforeEach } from 'vitest';

vi.mock('next-auth', () => ({
  getServerSession: vi.fn(),
}));

vi.mock('@/lib/prisma', () => ({
  default: {
    routine: {
      findMany: vi.fn(),
      create: vi.fn(),
    },
  },
}));

describe('Routines API', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('GET /api/routines', () => {
    it('returns 401 if unauthorized', async () => {
      vi.mocked(getServerSession).mockResolvedValueOnce(null);
      
      const res = await GET();
      expect(res.status).toBe(401);
      const data = await res.json();
      expect(data.error).toBe('Unauthorized');
    });

    it('returns routines for authenticated user', async () => {
      vi.mocked(getServerSession).mockResolvedValueOnce({ user: { id: 'user-1' } } as any);
      
      const mockRoutines = [{ id: 'r1', name: 'Push' }];
      vi.mocked(prisma.routine.findMany).mockResolvedValueOnce(mockRoutines as any);

      const res = await GET();
      expect(res.status).toBe(200);
      const data = await res.json();
      expect(data).toEqual(mockRoutines);
      expect(prisma.routine.findMany).toHaveBeenCalledWith(expect.objectContaining({
        where: { userId: 'user-1' }
      }));
    });

    it('returns 500 on db error', async () => {
      vi.mocked(getServerSession).mockResolvedValueOnce({ user: { id: 'user-1' } } as any);
      vi.mocked(prisma.routine.findMany).mockRejectedValueOnce(new Error('DB Error'));

      const res = await GET();
      expect(res.status).toBe(500);
    });
  });

  describe('POST /api/routines', () => {
    it('returns 401 if unauthorized', async () => {
      vi.mocked(getServerSession).mockResolvedValueOnce(null);
      const req = new Request('http://localhost/api/routines', { method: 'POST', body: JSON.stringify({}) });
      
      const res = await POST(req);
      expect(res.status).toBe(401);
    });

    it('returns 400 for invalid data', async () => {
      vi.mocked(getServerSession).mockResolvedValueOnce({ user: { id: 'user-1' } } as any);
      const req = new Request('http://localhost/api/routines', { 
        method: 'POST', 
        body: JSON.stringify({ name: '' }) 
      });
      
      const res = await POST(req);
      expect(res.status).toBe(400);
    });

    it('creates a new routine successfully', async () => {
      vi.mocked(getServerSession).mockResolvedValueOnce({ user: { id: 'user-1' } } as any);
      
      const reqBody = {
        name: 'New Routine',
        exercises: [{ exerciseId: 'e1', order: 0, targetSets: 3, targetReps: '10' }]
      };
      const req = new Request('http://localhost/api/routines', { 
        method: 'POST', 
        body: JSON.stringify(reqBody) 
      });

      const mockCreated = { id: 'r2', name: 'New Routine' };
      vi.mocked(prisma.routine.create).mockResolvedValueOnce(mockCreated as any);

      const res = await POST(req);
      expect(res.status).toBe(201);
      const data = await res.json();
      expect(data).toEqual(mockCreated);
      expect(prisma.routine.create).toHaveBeenCalledWith(expect.objectContaining({
        data: expect.objectContaining({
          name: 'New Routine',
          userId: 'user-1'
        })
      }));
    });

    it('returns 500 on db error', async () => {
      vi.mocked(getServerSession).mockResolvedValueOnce({ user: { id: 'user-1' } } as any);
      const req = new Request('http://localhost/api/routines', { 
        method: 'POST', 
        body: JSON.stringify({ name: 'n', exercises: [] }) 
      });
      vi.mocked(prisma.routine.create).mockRejectedValueOnce(new Error('db fail'));

      const res = await POST(req);
      expect(res.status).toBe(500);
    });
  });
});

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";

// GET all routines for the user
export async function GET() {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const routines = await prisma.routine.findMany({
      where: { userId: session.user.id },
      include: {
        exercises: {
          include: { exercise: true },
          orderBy: { order: 'asc' }
        }
      },
      orderBy: { createdAt: 'desc' }
    });
    
    return NextResponse.json(routines);
  } catch (error) {
    console.error("Error fetching routines:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

// CREATE a new routine
export async function POST(req: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await req.json();
    const { name, exercises } = body;

    if (!name || !Array.isArray(exercises)) {
      return NextResponse.json({ error: "Invalid data" }, { status: 400 });
    }

    const newRoutine = await prisma.routine.create({
      data: {
        userId: session.user.id,
        name,
        exercises: {
          create: exercises.map((e: any) => ({
            exerciseId: e.exerciseId,
            order: e.order,
            targetSets: e.targetSets,
            targetReps: e.targetReps || null
          }))
        }
      },
      include: {
        exercises: { include: { exercise: true } }
      }
    });

    return NextResponse.json(newRoutine, { status: 201 });
  } catch (error) {
    console.error("Error creating routine:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

