      <hr className="border-black/5 " />

      <div>
        <h3 className="text-lg font-bold mb-4">Integrations</h3>
        <div className="space-y-4">
          <div className="flex items-center justify-between p-4 rounded-xl border border-(--border) bg-transparent  ">
