import prisma from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { describe, it, expect, vi, beforeEach } from 'vitest';

vi.mock('@/lib/prisma', () => ({
  default: {
    user: {
      findUnique: vi.fn(),
    },
  },
}));

vi.mock('bcryptjs', () => ({
  default: {
    compare: vi.fn(),
  },
}));

const mocks = vi.hoisted(() => ({
  capturedAuthorize: null as any
}));

vi.mock('next-auth/providers/credentials', () => ({
  default: (options: any) => {
    mocks.capturedAuthorize = options.authorize;
    return { id: 'credentials', name: 'Email and Password' };
  }
}));

// Force import order so mock captures the options
import { authOptions } from './auth';

describe('Auth Options', () => {
  const TEST_VALID_SECRET = 'secret-val-1';
  const TEST_HASH = 'hashed-password-123';
  const TEST_INVALID_SECRET = 'secret-val-2';

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('CredentialsProvider Authorize', () => {
    it('throws error if credentials missing', async () => {
      await expect(mocks.capturedAuthorize(null)).rejects.toThrow('Please enter both email and password');
      await expect(mocks.capturedAuthorize({ email: 'test@test.com' })).rejects.toThrow('Please enter both email and password');
    });

    it('throws error if user not found or no password', async () => {
      vi.mocked(prisma.user.findUnique).mockResolvedValueOnce(null);
      await expect(mocks.capturedAuthorize({ email: 'test@test.com', password: TEST_VALID_SECRET })).rejects.toThrow('No user found with this email');
      
      vi.mocked(prisma.user.findUnique).mockResolvedValueOnce({ email: 'test@test.com' } as any);
      await expect(mocks.capturedAuthorize({ email: 'test@test.com', password: TEST_VALID_SECRET })).rejects.toThrow('No user found with this email');
    });

    it('throws error if password invalid', async () => {
      vi.mocked(prisma.user.findUnique).mockResolvedValueOnce({ 
        email: 'test@test.com', 
        password: TEST_HASH 
      } as any);
      vi.mocked(bcrypt.compare).mockResolvedValueOnce(false as never);

      await expect(mocks.capturedAuthorize({ email: 'test@test.com', password: TEST_INVALID_SECRET })).rejects.toThrow('Invalid password');
    });

    it('returns user if valid', async () => {
      const mockUser = {
        id: 'u1',
        email: 'test@test.com',
        name: 'Test',
        image: 'img.png',
        password: TEST_HASH
      };
      
      vi.mocked(prisma.user.findUnique).mockResolvedValueOnce(mockUser as any);
      vi.mocked(bcrypt.compare).mockResolvedValueOnce(true as never);

      const result = await mocks.capturedAuthorize({ email: 'test@test.com', password: TEST_VALID_SECRET });
      expect(result).toEqual({
        id: 'u1',
        email: 'test@test.com',
        name: 'Test',
        image: 'img.png'
      });
    });
  });

  describe('Callbacks', () => {
    it('jwt returns token with user id', async () => {
      const jwtCb = authOptions.callbacks?.jwt as any;
      const result = await jwtCb({ token: { orig: true }, user: { id: 'user123' }});
      expect(result).toEqual({ orig: true, id: 'user123' });
      
      const noUserResult = await jwtCb({ token: { orig: true }});
      expect(noUserResult).toEqual({ orig: true });
    });

    it('session maps token id to user id', async () => {
      const sessionCb = authOptions.callbacks?.session as any;
      const session = { user: { name: 'hi' } };
      const token = { id: 'tid' };
      const result = await sessionCb({ session, token });
      expect(result.user.id).toBe('tid');

      // Edge case: no user in session
      const noSessionUser = { user: undefined };
      const res2 = await sessionCb({ session: noSessionUser, token });
      expect(res2).toEqual({ user: undefined });
    });
  });
});

import { describe, it, expect } from 'vitest';
import {
  parseTab,
  toMeasurementForm,
  toMeasurementPayload,
  getTodayFoodLogs,
  sumNutrition,
  getLatestSleepLog,
  getTrackedDayCount,
  buildHistoryRows,
  getErrorMessage,
  buildDayTypeMap,
  getProteinTarget,
  getLocalDateKey,
} from './dashboard';
import type { FoodLog } from '@prisma/client';
import { EMPTY_MEASUREMENT_FORM } from './types';

describe('dashboard utilities', () => {
  describe('parseTab', () => {
    it('returns valid tab if provided', () => {
      expect(parseTab('body')).toBe('body');
      expect(parseTab('history')).toBe('history');
    });

    it('returns "chat" for invalid or null tab', () => {
      expect(parseTab('invalid')).toBe('chat');
      expect(parseTab(null)).toBe('chat');
    });
  });

  describe('toMeasurementForm', () => {
    it('returns empty form for null input', () => {
      expect(toMeasurementForm(null)).toEqual(EMPTY_MEASUREMENT_FORM);
    });

    it('converts measurement to form strings', () => {
      const m = { weight: 75.5, waist: 80 } as any;
      const form = toMeasurementForm(m);
      expect(form.weight).toBe('75.5');
      expect(form.waist).toBe('80');
      expect(form.chest).toBe('');
    });
  });

  describe('toMeasurementPayload', () => {
    it('converts form strings back to numbers or null', () => {
      const form: any = { 
        weight: '75.5', waist: '', chest: 'abc',
        arms: '', thighs: '', hips: '', calves: '', neck: '', bodyFat: ''
      };
      const payload = toMeasurementPayload(form);
      expect(payload.weight).toBe(75.5);
      expect(payload.waist).toBeNull();
      expect(payload.chest).toBeNull();
    });
  });

  describe('sumNutrition', () => {
    it('sums kcal and protein correctly', () => {
      const logs = [
        { kcal: 500, protein: 30, carbs: 50, fats: 10, fiber: 5 },
        { kcal: 300, protein: 20, carbs: 40, fats: 5, fiber: 2 },
      ] as FoodLog[];
      const totals = sumNutrition(logs);
      expect(totals.calories).toBe(800);
      expect(totals.protein).toBe(50);
      expect(totals.carbs).toBe(90);
    });
  });

  describe('getTrackedDayCount', () => {
    it('counts unique days across categories', () => {
      const logs = {
        food: [{ time: new Date('2024-01-01T10:00:00Z') }],
        workouts: [{ time: new Date('2024-01-01T15:00:00Z') }, { time: new Date('2024-01-02T10:00:00Z') }],
        sleep: [{ time: new Date('2024-01-03T10:00:00Z') }],
      } as any;
      expect(getTrackedDayCount(logs)).toBe(3);
    });
  });

  describe('getProteinTarget', () => {
    const goals = { proteinTarget: 150, proteinTraining: 180, proteinRest: 120 } as any;
    it('returns correct target for day type', () => {
      expect(getProteinTarget(goals, 'Training')).toBe(180);
      expect(getProteinTarget(goals, 'Rest')).toBe(120);
      expect(getProteinTarget(goals, 'Lite' as any)).toBe(150); // Fallback to proteinTarget if lite not set
    });
  });

  describe('buildDayTypeMap', () => {
    it('converts array to map', () => {
      const entries = [
        { dayKey: '2024-01-01', dayType: 'Training' },
        { dayKey: '2024-01-02', dayType: 'Rest' },
      ] as any;
      const map = buildDayTypeMap(entries);
      expect(map['2024-01-01']).toBe('Training');
      expect(map['2024-01-02']).toBe('Rest');
    });
  });

  describe('buildHistoryRows', () => {
    it('aggregates data into daily rows', () => {
      const logs = {
        food: [{ time: new Date('2024-01-01'), kcal: 2000, protein: 150, carbs: 200, fats: 70, fiber: 30 }],
        workouts: [{ time: new Date('2024-01-01'), focus: 'Legs' }],
        sleep: [{ time: new Date('2024-01-01'), hours: 8 }],
      } as any;
      const goals = { proteinTarget: 160 } as any;
      const map = { '2024-01-01': 'Training' } as any;
      
      const rows = buildHistoryRows(logs, goals, map);
      expect(rows).toHaveLength(1);
      expect(rows[0].workout).toBe('Legs');
      expect(rows[0].kcal).toBe(2000);
      expect(rows[0].protein).toBe(150);
      expect(rows[0].status).toBe('pending'); // 150 < 160
    });
  });

  describe('getErrorMessage', () => {
    it('extracts message from Error object', () => {
      expect(getErrorMessage(new Error('Test error'))).toBe('Test error');
    });
    it('returns fallback for non-error types', () => {
      expect(getErrorMessage('string error')).toBe('Unknown error');
    });
  });

  describe('getLocalDateKey', () => {
    it('formats date correctly as YYYY-MM-DD', () => {
      const d = new Date(2024, 0, 15); // Jan 15 2024
      expect(getLocalDateKey(d)).toBe('2024-01-15');
    });
  });

  describe('getTodayFoodLogs', () => {
    it('filters logs for today', () => {
      const today = new Date();
      const logs = [
        { time: today },
        { time: new Date('2020-01-01') }
      ] as FoodLog[];
      expect(getTodayFoodLogs(logs)).toHaveLength(1);
    });
  });

  describe('getLatestSleepLog', () => {
    it('returns first log if exists', () => {
      expect(getLatestSleepLog([{ hours: 8 }] as any)).toEqual({ hours: 8 });
      expect(getLatestSleepLog([])).toBeNull();
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { persistLogData } from './persistence';
import prisma from './prisma';

// Mock prisma client
vi.mock('./prisma', () => ({
  default: {
    $transaction: vi.fn(),
  },
}));

describe('persistence utility', () => {
  const userId = 'user-123';
  const mockTx = {
    foodLog: { findFirst: vi.fn(), update: vi.fn(), create: vi.fn() },
    workoutLog: { findFirst: vi.fn(), update: vi.fn(), create: vi.fn() },
    sleepLog: { findFirst: vi.fn(), update: vi.fn(), create: vi.fn() },
    bodyMeasurement: { findFirst: vi.fn(), update: vi.fn(), create: vi.fn() },
    userProfile: { upsert: vi.fn() },
    goal: { upsert: vi.fn() },
    dayTypeEntry: { upsert: vi.fn() },
    exercise: { findFirst: vi.fn() },
  };

  beforeEach(() => {
    vi.clearAllMocks();
    (prisma.$transaction as any).mockImplementation((cb: any) => cb(mockTx));
  });

  describe('persistLogData', () => {
    it('returns early if no envelopes are provided', async () => {
      await persistLogData([], userId);
      expect(prisma.$transaction).not.toHaveBeenCalled();
    });

    it('skips envelopes without a category', async () => {
      await persistLogData([{ data: {} } as any], userId);
      expect(prisma.$transaction).not.toHaveBeenCalled();
    });

    it('persists food logs (single item)', async () => {
      const envelopes = [
        {
          category: 'food',
          data: { name: 'Apple', kcal: 95, protein: 0.5, carbs: 25, fats: 0.3, fiber: 4.4 }
        }
      ];
      await persistLogData(envelopes, userId);
      expect(mockTx.foodLog.create).toHaveBeenCalledWith({
        data: expect.objectContaining({ name: 'Apple', kcal: 95 })
      });
    });

    it('persists food logs (array of items)', async () => {
      const envelopes = [
        {
          category: 'food',
          data: {
            items: [
              { name: 'Eggs', kcal: 140 },
              { name: 'Toast', kcal: 100 }
            ]
          }
        }
      ];
      await persistLogData(envelopes, userId);
      expect(mockTx.foodLog.create).toHaveBeenCalledTimes(2);
    });

    it('updates existing food log if update flag is set', async () => {
      mockTx.foodLog.findFirst.mockResolvedValue({ id: 'existing-id' });
      const envelopes = [
        {
          category: 'food',
          data: { name: 'Apple', kcal: 100, update: true, date: '2024-01-01' }
        }
      ];
      await persistLogData(envelopes, userId);
      expect(mockTx.foodLog.update).toHaveBeenCalledWith({
        where: { id: 'existing-id' },
        data: expect.objectContaining({ kcal: 100 })
      });
    });

    it('persists workout log', async () => {
      mockTx.exercise.findFirst.mockResolvedValue({ id: 'exercise-id' });
      const envelopes = [
        {
          category: 'workout',
          data: {
            focus: 'Upper Body',
            volume: 5000,
            exercises: [
              { name: 'Bench Press', sets: [{ setNumber: 1, reps: 10, weight: 60 }] }
            ]
          }
        }
      ];
      await persistLogData(envelopes, userId);
      expect(mockTx.workoutLog.create).toHaveBeenCalledWith(expect.objectContaining({
        data: expect.objectContaining({ focus: 'Upper Body' })
      }));
    });

    it('updates existing workout log', async () => {
      mockTx.workoutLog.findFirst.mockResolvedValue({ id: 'workout-id' });
      const envelopes = [
        {
          category: 'workout',
          data: { focus: 'Upper Body', update: true, date: '2024-01-01' }
        }
      ];
      await persistLogData(envelopes, userId);
      expect(mockTx.workoutLog.update).toHaveBeenCalled();
    });

    it('persists sleep log', async () => {
      const envelopes = [{ category: 'sleep', data: { hours: 8, bed: '22:00', wake: '06:00' } }];
      await persistLogData(envelopes, userId);
      expect(mockTx.sleepLog.create).toHaveBeenCalled();
    });

    it('updates sleep log', async () => {
      mockTx.sleepLog.findFirst.mockResolvedValue({ id: 'sleep-id' });
      const envelopes = [{ category: 'sleep', data: { hours: 7, update: true } }];
      await persistLogData(envelopes, userId);
      expect(mockTx.sleepLog.update).toHaveBeenCalled();
    });

    it('persists measurements', async () => {
      const envelopes = [{ category: 'measurement', data: { weight: 70, waist: 80 } }];
      await persistLogData(envelopes, userId);
      expect(mockTx.bodyMeasurement.create).toHaveBeenCalled();
    });

    it('updates measurements', async () => {
      mockTx.bodyMeasurement.findFirst.mockResolvedValue({ id: 'm-id' });
      const envelopes = [{ category: 'measurement', data: { weight: 71, update: true } }];
      await persistLogData(envelopes, userId);
      expect(mockTx.bodyMeasurement.update).toHaveBeenCalled();
    });

    it('persists profile updates', async () => {
      const envelopes = [{ category: 'profile', data: { name: 'John', age: 30 } }];
      await persistLogData(envelopes, userId);
      expect(mockTx.userProfile.upsert).toHaveBeenCalled();
    });

    it('persists goal updates', async () => {
      const envelopes = [{ category: 'goals', data: { targetWeight: 75 } }];
      await persistLogData(envelopes, userId);
      expect(mockTx.goal.upsert).toHaveBeenCalled();
    });

    it('persists dayType updates', async () => {
      const envelopes = [{ category: 'dayType', data: { dayType: 'Training', dayKey: '2024-01-01' } }];
      await persistLogData(envelopes, userId);
      expect(mockTx.dayTypeEntry.upsert).toHaveBeenCalledWith(expect.objectContaining({
        create: expect.objectContaining({ dayType: 'Training' })
      }));
    });

    it('normalizes dayType values', async () => {
        const testCases = [
            { input: 'train', expected: 'Training' },
            { input: 'rest day', expected: 'Rest' },
            { input: 'lite workout', expected: 'Lite' },
            { input: 'unknown', expected: 'Rest' },
        ];

        for (const tc of testCases) {
            await persistLogData([{ category: 'dayType', data: { type: tc.input } }], userId);
            expect(mockTx.dayTypeEntry.upsert).toHaveBeenLastCalledWith(expect.objectContaining({
                create: expect.objectContaining({ dayType: tc.expected })
            }));
        }
    });

    it('throws error if persistence fails within transaction', async () => {
      (prisma.$transaction as any).mockImplementation(() => {
        throw new Error('Transaction failed');
      });
      await expect(persistLogData([{ category: 'food', data: { name: 'X' } }], userId)).rejects.toThrow('Transaction failed');
    });

    it('skips invalid food items', async () => {
        const envelopes = [{ category: 'food', data: { name: '', kcal: 100 } }];
        await persistLogData(envelopes as any, userId);
        expect(mockTx.foodLog.create).not.toHaveBeenCalled();
    });

    it('skips invalid workout items', async () => {
        const envelopes = [{ category: 'workout', data: { focus: '', volume: 100 } }];
        await persistLogData(envelopes as any, userId);
        expect(mockTx.workoutLog.create).not.toHaveBeenCalled();
    });

    it('skips invalid sleep items', async () => {
        const envelopes = [{ category: 'sleep', data: { date: 'not-a-date' } }];
        await persistLogData(envelopes as any, userId);
        expect(mockTx.sleepLog.create).not.toHaveBeenCalled();
    });

    it('skips invalid measurement items', async () => {
        const envelopes = [{ category: 'measurement', data: { date: 'not-a-date' } }];
        await persistLogData(envelopes as any, userId);
        expect(mockTx.bodyMeasurement.create).not.toHaveBeenCalled();
    });

    it('skips invalid profile items', async () => {
        const envelopes = [{ category: 'profile', data: { age: -5 } }];
        await persistLogData(envelopes as any, userId);
        expect(mockTx.userProfile.upsert).not.toHaveBeenCalled();
    });

    it('skips invalid goal items', async () => {
        const envelopes = [{ category: 'goals', data: { kcalTarget: -100 } }];
        await persistLogData(envelopes as any, userId);
        expect(mockTx.goal.upsert).not.toHaveBeenCalled();
    });

    it('handles non-object data gracefully in helpers', async () => {
        // This triggers isRecord(value) returning false
        await persistLogData([{ category: 'sleep', data: "not-an-object" }], userId);
        expect(mockTx.sleepLog.create).not.toHaveBeenCalled();
    });
  });
});
